package com.creatorkanata.pneutouchai.web

import android.content.res.AssetManager
import android.util.Log
import android.webkit.WebResourceResponse
import androidx.webkit.WebViewAssetLoader
import java.io.IOException

const val APP_HOST = "appassets.androidplatform.net"
const val START_URL = "https://$APP_HOST/demo-visualizer/"

// URL prefix -> asset directory, generated by the prepareWebAssets Gradle task (same layout as tools/serve_demo.py).
private val DIRECTORIES = listOf(
    "/demo-visualizer/" to "web/demo-visualizer",
    "/shared/" to "web/shared",
    "/videos/demo/" to "web/videos/demo",
    "/images/demo/" to "web/images/demo",
    "/images/logo/" to "web/images/logo",
)

fun buildAssetLoader(assets: AssetManager): WebViewAssetLoader {
    val builder = WebViewAssetLoader.Builder().setDomain(APP_HOST)
    DIRECTORIES.forEach { (prefix, dir) -> builder.addPathHandler(prefix, DirectoryHandler(assets, dir)) }
    return builder.addPathHandler("/", SingleFileHandler(assets, "config.json", "web/config.json")).build()
}

private class DirectoryHandler(private val assets: AssetManager, private val baseDir: String) :
    WebViewAssetLoader.PathHandler {
    override fun handle(path: String): WebResourceResponse? = assetPathFor(baseDir, path)?.let { openAsset(assets, it) }
}

private class SingleFileHandler(private val assets: AssetManager, private val name: String, private val assetPath: String) :
    WebViewAssetLoader.PathHandler {
    override fun handle(path: String): WebResourceResponse? = if (path == name) openAsset(assets, assetPath) else null
}

/** 200 response with the full length, so [withRange] can turn it into a 206 slice. Null when missing. */
private fun openAsset(assets: AssetManager, assetPath: String): WebResourceResponse? {
    val stream = try {
        assets.open(assetPath, AssetManager.ACCESS_STREAMING)
    } catch (error: IOException) {
        Log.d("PneuTouchAssets", "not found: $assetPath")
        return null
    }
    // AssetInputStream.available() is the remaining (uncompressed) length of the asset.
    val size = stream.available().toLong()
    val mime = mimeTypeFor(assetPath)
    val encoding = if (mime.startsWith("text/") || mime == "application/json") "utf-8" else null
    return WebResourceResponse(mime, encoding, 200, "OK", fileHeaders(size), stream)
}

fun fileHeaders(length: Long): Map<String, String> = mapOf(
    "Content-Length" to length.toString(),
    "Accept-Ranges" to "bytes",
    "Cache-Control" to "no-cache",
    "X-Content-Type-Options" to "nosniff",
)
